export const SingleTimeSeries = zod.object({
  "association_id": zod.int().describe('Surrogate id of this association, minted by the store that holds it. Assigned once when the association is created and never changed: renaming the series or reassigning its owner leaves it alone, so a consumer may persist it as a durable reference. Ids are never reused, and they are store-local — resolve one against the same store the document was exported from, not against an independently built store. Assigned by the store, never by a document author.'),
  "owner_id": zod.int().describe('ID of the owning component or supplemental attribute. The producing data layer allocates both from one id stream, so an `owner_id` never collides across the two categories; `owner_category` remains required because the store\'s catalog contract still supports independent streams from other producers, and it is still the store\'s disambiguator.'),
  "owner_type": zod.string().describe('Type name of the owning entity. Descriptive, not part of the series\' identity.'),
  "owner_category": zod.enum(['Component', 'SupplementalAttribute']).describe('Whether a time series\' owner is a component or a supplemental attribute. The producing data layer allocates both kinds of id from one stream, so an owner_id never names one of each; the category is required regardless, because the store\'s catalog contract still supports independent streams from other producers and remains the store\'s disambiguator. These are the display and serde spellings; the store\'s catalog holds them as the integer codes 0 and 1.'),
  "time_series_type": zod.enum(['SingleTimeSeries']).default(singleTimeSeriesTimeSeriesTypeDefault).describe('Discriminator. Fixed to SingleTimeSeries for this schema, pinned with `const` to match this repo\'s existing discriminators (Core/common.json\'s `curve_type`), which generate a plain string literal in both toolchains.'),
  "name": zod.string().describe('Time series name (e.g. max_active_power). Part of the series\' identity, and often carrying a disambiguating suffix; `component_field` records what the values are for.'),
  "features": zod.record(zod.string(), zod.union([zod.int(),zod.number(),zod.boolean(),zod.string()]).describe('One feature value. Four kinds, matching the backing store\'s feature-value type: int, float, bool, str. `anyOf` rather than `oneOf` is required, not stylistic: JSON Schema\'s `integer` is a subset of `number`, so an integer instance matches both branches and `oneOf` — which demands exactly one match — would reject every integer feature. A float feature is compared and hashed by its bit pattern rather than by IEEE comparison, so 0.0 and -0.0 are two different series; NaN and negative zero are rejected on write because the catalog cannot store either faithfully.')).describe('User-defined key/value tags forming part of a series\' identity. A map, matching the backing store\'s feature-map type (a BTreeMap whose sort order is load-bearing, because the hash of the feature map keys the catalog\'s uniqueness index). The excluded property names each already name a field of a time series or of the tuple that addresses one: consumers routinely spread a feature map into keyword arguments, where a feature called `name` or `resolution` would shadow the real field and silently change what a query means. The comparison is exact and case-sensitive — `resolution` is reserved, `Resolution` is not.'),
  "uri": zod.string().describe('Locator for the dense data, unique within one store. No required format — typically a file path or an HDF5 dataset path; the backing store decides what it means and resolves it (infrastore uses its content hash as this value). Never parsed or interpreted here. This layer records where the values are, never the values.'),
  "data_hash": zod.string().optional().describe('Content hash of the stored array: SHA-256, hex-encoded. Optional — not every producer computes it.'),
  "element_type": zod.string().describe('Canonical element type of the stored array: a dtype spelling (`f64`, `f32`, `i64`, `i32`, `u64`, `u32`, `u16`, `u8`, `i16`, `i8`, `bool`) for plain scalars, else `tuple(N,dtype)` or a function-data kind (`linear_function`, `quadratic_function`, `piecewise_linear`, `piecewise_step`). It says what one timestep\'s value means and how it is laid out; the physical dtype of the bytes derives from it rather than being recorded separately. `linear_function` occupies 2 slots, `quadratic_function` 3; the two piecewise kinds are ragged, with the used count in the row\'s leading element.'),
  "element_shape": zod.array(zod.int().min(singleTimeSeriesElementShapeItemMin)).describe('Per-step element shape: the trailing dims after time. An empty array means a scalar element.'),
  "array_shape": zod.array(zod.int().min(singleTimeSeriesArrayShapeItemMin)).min(1).optional().describe('Full native shape of the stored array, in the order the store holds it: the first axis is the array\'s length and the trailing axes end with `element_shape`. Static types are `[length, *element_shape]`; a deterministic forecast stacks windows as `[horizon_count, count, *element_shape]`; probabilistic and scenarios forecasts add a percentile or scenario axis in front of that. Optional, and redundant for the static types, where it is exactly `[length] + element_shape`. It earns its place on the forecasts, whose array layout is a convention the producing package owns rather than a rule this layer enforces, so the stored geometry cannot be reconstructed from `horizon`, `count`, `percentiles`, and `scenario_count` alone. A consumer that has it should prefer it; one that does not falls back to those fields, which is exact for the static types and a best effort for the forecasts.'),
  "units": zod.string().optional().describe('Unit label for the series values. Set by whoever creates the series and returned unchanged; not part of the series\' identity, so two series differing only in this label are duplicates. Meaningless on its own when `unit_system` is a per-unit basis, where the values are dimensionless. By convention drawn from the unit vocabulary in Core/units.json, though this field is a free-text label the store does not validate against it.'),
  "quantity_kind": zod.string().optional().describe('Kind of physical quantity the values measure (e.g. ActivePower, ReactivePower, ElectricalEnergy). Coarser than `units` but finer than a dimension: ActivePower, ReactivePower, and ApparentPower share the dimension {M:1,L:2,T:-3}, so a dimension cannot tell them apart and a quantity kind can. It is also the only record of what the values measure when `unit_system` is a per-unit basis.'),
  "unit_system": zod.enum(['COMPONENT_BASE', 'NATURAL_UNITS']).optional().describe('Unit basis a stored value is expressed in. COMPONENT_BASE: per-unit against a base the component records itself. NATURAL_UNITS: the quantity\'s own physical unit. No system-wide option: a value per-unitized against a shared base records that base on the component and rides as COMPONENT_BASE. Used in three scopes, each read against its own record rather than a document-wide table: a component\'s own `power_units` (against that component\'s `base_power`), a cost payload\'s own `power_units` (e.g. `CostCurve`, against the owning component\'s `base_power`), and a time series association\'s own `unit_system` (governing only that one series).'),
  "time_reference": zod.string().optional().describe('How a series\' timestamps were spelled, recorded so a read hands back what the write declared instead of relabelling every series UTC. Four forms share one string, and are unambiguous because a zone name that would read as either literal or as an offset is rejected: `utc`; `zoneless` for a wall clock, which names no instant; a fixed UTC offset (`-07:00`, `+0530`, `+05`); or an IANA zone name (`America/Denver`). Only the name\'s shape is checked here — whether a zone exists is a tz-database question, and the store records the name either way. A spelling, not a grid: it does not change what a calendar `resolution` steps on, and a series on a local-clock grid is a NonSequentialTimeSeries. Descriptive, so two series differing only in it are duplicates rather than distinct series, but not inert — a query\'s bounds must match the series\' spelling, and the zoneless series form their own group.'),
  "component_field": zod.string().optional().describe('The field on the owning component or supplemental attribute whose value these values are the time-varying form of (e.g. max_active_power, rating). Free-form: it names a field in the consumer\'s own object model. Records what the values are for, where `name` only says which series they are.'),
  "application_data": zod.string().optional().describe('Opaque, package-owned payload (typically JSON) carried verbatim for an application to reconstruct its own domain objects. Never parsed or interpreted here, and end users are not expected to set it. Element typing does not belong here — that is `element_type`.'),
  "initial_timestamp": zod.iso.datetime({"offset":true}).describe('First timestamp of the regular grid; every later step lands at `initial_timestamp + k * resolution`. An RFC3339 string with at most 3 fractional-second digits: the store\'s floor is one millisecond, matching Julia\'s millisecond-precision DateTime.'),
  "resolution": zod.string().describe('A time period as an ISO-8601 duration string, used for `resolution`, `horizon`, and `interval`. Two kinds, which are never equal even when their spans coincide: fixed spans (`PT1H`, `PT5M`, down to a one-millisecond floor of `PT0.001S`) and calendar spans (`P1M`, `P1Y`), whose length depends on the calendar. `PT0S` is the canonical interval of a single-window forecast. More than three fractional-second digits is rejected, so a series on a grid finer than a millisecond is not storable at all rather than storable and unreadable.'),
  "length": zod.int().min(singleTimeSeriesLengthMin).describe('Number of timesteps.')
}).describe('A static time series on a regular grid: values at `initial_timestamp + k * resolution`. One of a closed set of six canonical time series types owned by the data layer. This schema records the association and its metadata; the dense values live in the store named by `uri`.')

